import { describe, expect, it } from "vitest";

import {
  hmacHex,
  issueApiKey,
  makeLookup,
  parseToken,
  verifyToken,
} from "./api-key.crypto";

process.env.SECRET_KEY = "test-secret-key-migration-fixture";
process.env.ENCRYPTION_KEY_SALT = "test-salt-migration-fixture";

/**
 * Vectors generated by the LEGACY Python implementation
 * (apps/api_keys/services.py (rebranded): _hmac_hex/_make_lookup) with the env vars above.
 * If these break, every existing 2post_ key stops working after cutover.
 */
const PYTHON_HMAC = "87530b4c3d0faa6604446b40a5fa2a9b5e46615d922a54c3c0d38ffd28f31328";
const PYTHON_LOOKUP = "84d168a1";
const RANDOM_PART = "fixture-random-part-123";

describe("ApiKey crypto (byte-compat with apps/api_keys/services.py (rebranded))", () => {
  it("computes the same HMAC and lookup as the legacy Python code", () => {
    expect(hmacHex(RANDOM_PART)).toBe(PYTHON_HMAC);
    expect(makeLookup(RANDOM_PART)).toBe(PYTHON_LOOKUP);
  });

  it("issues keys in the 2post_<random>_<lookup8> format", () => {
    const key = issueApiKey();
    expect(key.raw.startsWith("2post_")).toBe(true);
    const parsed = parseToken(key.raw)!;
    expect(parsed.lookupPrefix).toBe(key.lookupPrefix);
    expect(verifyToken(key.raw, key.tokenHash)).toBe(true);
  });

  it("parses tokens whose secret contains underscores (rsplit on last _)", () => {
    const raw = "2post_a_b_c-d_e-verylongsecret_1a2b3c4d";
    const parsed = parseToken(raw)!;
    expect(parsed.randomPart).toBe("a_b_c-d_e-verylongsecret");
    expect(parsed.lookupPrefix).toBe("1a2b3c4d");
  });

  it("rejects malformed tokens", () => {
    expect(parseToken("wrong_prefix_x_y")).toBeNull();
    expect(parseToken("2post_noseparator")).toBeNull();
    expect(parseToken("2post_secret_short7")).toBeNull(); // lookup must be 8 chars
    expect(parseToken(undefined)).toBeNull();
    expect(verifyToken("garbage", PYTHON_HMAC)).toBe(false);
  });
});
